class Capture extends AudioWorkletProcessor {
    constructor() {
        super();
        this.size = 4096;
        this.buffer = new Float32Array(this.size);
        this.filled = 0;
        this.started = false;
        this.active = true;
        this.port.onmessage = (event) => {
            if (event.data === 'stop') {
                if (this.filled > 0) this.port.postMessage({ chunk: this.buffer.slice(0, this.filled) });
                this.port.postMessage({ done: true });
                this.active = false;
            }
        };
    }

    process(inputs) {
        if (!this.active) return false;
        const channel = inputs[0] && inputs[0][0];
        if (!channel) return true;

        if (!this.started) {
            this.started = true;
            this.port.postMessage({ first: currentTime });
        }

        let index = 0;
        while (index < channel.length) {
            const take = Math.min(channel.length - index, this.size - this.filled);
            this.buffer.set(channel.subarray(index, index + take), this.filled);
            this.filled += take;
            index += take;

            if (this.filled === this.size) {
                this.port.postMessage({ chunk: this.buffer });
                this.buffer = new Float32Array(this.size);
                this.filled = 0;
            }
        }

        return true;
    }
}

